using System;using System.IO;using System.Linq;using System.Collections.Generic;using Microsoft.Win32;using UnityEngine;
public static class ValidationNative12 {
 static string Json(object o)=>(string)AppDomain.CurrentDomain.GetAssemblies().First(a=>a.GetName().Name=="Newtonsoft.Json").GetType("Newtonsoft.Json.JsonConvert").GetMethod("SerializeObject",new[]{typeof(object)}).Invoke(null,new[]{o});
 public static object Main()=>Capture("original-native-registry.json");
 public static object Capture(string filename){if(Path.GetFileName(filename)!=filename)throw new Exception("Evidence basename required");string file="outputs/chapter45-detailed-design-2026-10-03/validation-cycle12/"+filename;if(File.Exists(file))throw new Exception("Preserve registry evidence");var results=new List<object>();foreach(string path in new[]{@"Software\Unity\UnityEditor\DefaultCompany\tralalero Shooter",@"Software\DefaultCompany\tralalero Shooter"}){using var key=Registry.CurrentUser.OpenSubKey(path,false);if(key==null){results.Add(new{path,exists=false});continue;}var rows=key.GetValueNames().OrderBy(x=>x).Select(name=>new{name,kind=key.GetValueKind(name).ToString(),value=key.GetValue(name) is byte[] bytes?Convert.ToBase64String(bytes):key.GetValue(name)}).ToArray();results.Add(new{path,exists=true,rows});}File.WriteAllText(file,Json(results));return new{file,coin=PlayerPrefs.GetInt("coin"),jewel=PlayerPrefs.GetInt("jewel"),pid=System.Diagnostics.Process.GetCurrentProcess().Id};}
}
